// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public { c = new RoundFactory(); }
    function testFuzz_property(address initializer, address querier) public {
        vm.assume(initializer != address(0));
        vm.assume(querier != initializer);
        vm.prank(initializer);
        c.initialize();
        vm.prank(querier);
        assertTrue(c.owner() == initializer, "owner() must report the stored owner to any caller");
    }
}
